module.exports = "import React, { Component } from 'react';\nimport { Player } from 'video-react';\nimport { Button, Form, FormGroup, Label, Input } from 'reactstrap';\n\nexport default class PlayerExample extends Component {\n  constructor(props, context) {\n    super(props, context);\n\n    this.state = {\n      playerSource: 'https://media.w3.org/2010/05/sintel/trailer_hd.mp4',\n      inputVideoUrl: 'http://www.w3schools.com/html/mov_bbb.mp4'\n    };\n\n    this.handleValueChange = this.handleValueChange.bind(this);\n    this.updatePlayerInfo = this.updatePlayerInfo.bind(this);\n  }\n\n  componentDidUpdate(prevProps, prevState) {\n    if (this.state.playerSource !== prevState.playerSource) {\n      this.player.load();\n    }\n  }\n\n  handleValueChange(e) {\n    const { value } = e.target;\n    this.setState({\n      inputVideoUrl: value\n    });\n  }\n\n  updatePlayerInfo() {\n    const { inputVideoUrl } = this.state;\n    this.setState({\n      playerSource: inputVideoUrl\n    });\n  }\n\n  render() {\n    return (\n      <div>\n        <Player\n          ref={player => {\n            this.player = player;\n          }}\n          videoId=\"video-1\"\n        >\n          <source src={this.state.playerSource} />\n        </Player>\n        <div className=\"docs-example\">\n          <Form>\n            <FormGroup>\n              <Label for=\"inputVideoUrl\">Video Url</Label>\n              <Input\n                name=\"inputVideoUrl\"\n                id=\"inputVideoUrl\"\n                value={this.state.inputVideoUrl}\n                onChange={this.handleValueChange}\n              />\n            </FormGroup>\n            <FormGroup>\n              <Button type=\"button\" onClick={this.updatePlayerInfo}>\n                Update\n              </Button>\n            </FormGroup>\n          </Form>\n        </div>\n      </div>\n    );\n  }\n}\n";